import { describe, expect, it, vi } from 'vitest';
import type { ChangeLogEntry } from '@asohav/shared';

vi.mock('../repo.js');

import * as repo from '../repo.js';

describe('appendChangeLog', () => {
  it('does not include an id key in the insert payload, letting the DB generate it', async () => {
    const entry: Omit<ChangeLogEntry, 'Id' | 'At'> = {
      Who: 'test-user',
      Action: 'create' as const,
      Collection: 'virtues',
      ObjectId: 'v-123',
      ObjectName: 'Test Virtue',
      Before: { Name: 'Old Name' },
      After: { Name: 'New Name' },
    };

    vi.mocked(repo.appendChangeLog).mockResolvedValue(undefined);

    await repo.appendChangeLog(entry);

    expect(repo supabaseAdmin.from('changelog').insert).toHaveBeenCalled();
    const insertCall = repo supabaseAdmin.from('changelog').insert.mock.calls[0][0] as Record<string, unknown>;
    expect(insertCall).not.toHaveProperty('id');
    expect(insertCall).toHaveProperty('at');
    expect(insertCall).toHaveProperty('who', entry.Who);
    expect(insertCall).toHaveProperty('action', entry.Action);
    expect(insertCall).toHaveProperty('collection', entry.Collection);
    expect(insertCall).toHaveProperty('object_id', entry.ObjectId);
    expect(insertCall).toHaveProperty('object_name', entry.ObjectName);
    expect(insertCall).toHaveProperty('before', entry.Before);
    expect(insertCall).toHaveProperty('after', entry.After);
  });

  it('maps camelCase entry fields to snake_case payload keys correctly', () => {
    const entry: Omit<ChangeLogEntry, 'Id' | 'At'> = {
      Who: 'test-user',
      Action: 'update' as const,
      Collection: 'items',
      ObjectId: 'item-x',
      ObjectName: 'Potion',
      Before: { name: 'Health Potion' },
      After: { name: 'Super Potion' },
    };

    vi.mocked(repo.appendChangeLog).mockResolvedValue(undefined);

    repo.appendChangeLog(entry);

    const insertCall = repo supabaseAdmin.from('changelog').insert.mock.calls[0][0];
    expect(insertCall.who).toBe('test-user');
    expect(insertCall.action).toBe('update');
    expect(insertCall.collection).toBe('items');
    expect(insertCall.object_id).toBe('item-x');
    expect(insertCall.object_name).toBe('Potion');
  });

  it('preserves the error if the mocked insert call rejects', async () => {
    const entry: Omit<ChangeLogEntry, 'Id' | 'At'> = {
      Who: 'test-user',
      Action: 'delete' as const,
      Collection: 'moves',
      ObjectId: 'm-abc',
      ObjectName: 'Defend',
      Before: undefined,
      After: undefined,
    };

    const errorMessage = 'Permission denied';
    const error = new Error(errorMessage) as any;
    error.status = 403;
    vi.mocked(repo supabaseAdmin.from('changelog').insert).mockRejectedValue(error);

    await expect(repo.appendChangeLog(entry)).rejects.toThrow(error);
  });
});

